class Enemy:
    hp: int

class Camera:
    target: weakref Enemy using Arena = None   # follows an enemy made in some Arena

fn load_level(ref mut cam: Camera, ref mut level: Arena):
    boss = Enemy(hp=500) using level
    cam.target = weakref boss                  # cam now reaches `level`
    println(boss.hp)

fn main():
    level = Arena.with_capacity(64 * 1024)     # made before cam, so it ends after cam
    cam = Camera()
    load_level(ref mut cam, ref mut level)
    if cam.target exists as e:                 # the boss ended with load_level; its block is still in `level`
        println(e.hp)
    else:
        println("gone")

