import std.thread

fn collect(ref mut level: Arena, parts: Array[Array[int]]) -> int:
    hits = Array.new_in(level)                      # Array[int] using Arena
    with scope = thread.scope():
        for part in parts:
            scope.spawn(owns fn() ref part: for x in part: hits.push(owns (x * 2)))   # a reduction ([THR-21])
    return hits.len()

